From bffccd7e288ed720ccb696ecefe640375796e107 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 21:19:54 +0100
Subject: [PATCH] applet: show saved networks in their own section

Networks with a saved connection were listed together with unknown
ones under "Available". Put them in a "Saved" section above the others,
which the sorting already keeps together, so the list is easier to scan.

BUG: 477333
---
 libs/models/appletproxymodel.cpp | 15 +++++++++++++++
 libs/models/appletproxymodel.h   |  2 ++
 libs/models/networkmodelitem.cpp |  2 +-
 3 files changed, 18 insertions(+), 1 deletion(-)

diff --git a/libs/models/appletproxymodel.cpp b/libs/models/appletproxymodel.cpp
index eceab62c3..4c55d72d2 100644
--- a/libs/models/appletproxymodel.cpp
+++ b/libs/models/appletproxymodel.cpp
@@ -11,6 +11,8 @@

 #include "configuration.h"

+#include <KLocalizedString>
+
 AppletProxyModel::AppletProxyModel(QObject *parent)
     : QSortFilterProxyModel(parent)
 {
@@ -24,6 +26,19 @@ AppletProxyModel::AppletProxyModel(QObject *parent)

 AppletProxyModel::~AppletProxyModel() = default;

+QVariant AppletProxyModel::data(const QModelIndex &index, int role) const
+{
+    if (role == NetworkModel::SectionRole) {
+        const QModelIndex sourceIndex = mapToSource(index);
+        if (sourceModel()->data(sourceIndex, NetworkModel::ConnectionStateRole).toUInt() == NetworkManager::ActiveConnection::Deactivated
+            && !sourceModel()->data(sourceIndex, NetworkModel::UuidRole).toString().isEmpty()) {
+            return i18nc("@title:column header for list of available network connections that have been saved before", "Saved");
+        }
+    }
+
+    return QSortFilterProxyModel::data(index, role);
+}
+
 bool AppletProxyModel::filterAcceptsRow(int source_row, const QModelIndex &source_parent) const
 {
     const QModelIndex index = sourceModel()->index(source_row, 0, source_parent);
diff --git a/libs/models/appletproxymodel.h b/libs/models/appletproxymodel.h
index ba1a99ba6..5508fc07a 100644
--- a/libs/models/appletproxymodel.h
+++ b/libs/models/appletproxymodel.h
@@ -22,6 +22,8 @@ public:
     explicit AppletProxyModel(QObject *parent = nullptr);
     ~AppletProxyModel() override;

+    QVariant data(const QModelIndex &index, int role = Qt::DisplayRole) const override;
+
 protected:
     bool filterAcceptsRow(int source_row, const QModelIndex &source_parent) const override;
     bool lessThan(const QModelIndex &left, const QModelIndex &right) const override;
diff --git a/libs/models/networkmodelitem.cpp b/libs/models/networkmodelitem.cpp
index 70d48fb6a..7cd895622 100644
--- a/libs/models/networkmodelitem.cpp
+++ b/libs/models/networkmodelitem.cpp
@@ -476,7 +476,7 @@ void NetworkModelItem::setUuid(const QString &uuid)
 {
     if (m_uuid != uuid) {
         m_uuid = uuid;
-        m_changedRoles << NetworkModel::UuidRole;
+        m_changedRoles << NetworkModel::UuidRole << NetworkModel::SectionRole;
     }
 }

